// Shipshape plank join. Joins every plank annotation to a current step-definition pattern,
// reports the pattern-to-scenario mapping, and reddens where the join fails.
// Derived at fitting out by Shipwright. Weakness: the annotation scan is a docblock-aware
// regex reader, not a full AST-with-comments reader.
import { readFileSync, readdirSync, statSync, existsSync } from 'node:fs';
import { join, extname } from 'node:path';

const ROOT = process.cwd();

function rigging() {
  const text = readFileSync(join(ROOT, 'RIGGING.md'), 'utf8');
  const values = {};
  let section = '';
  for (const line of text.split('\n')) {
    const heading = line.match(/^##\s+(.+)$/);
    if (heading) { section = heading[1].trim(); continue; }
    const item = line.match(/^-\s+([A-Za-z-]+):\s*(.+)$/);
    if (!item) continue;
    const key = `${section}/${item[1]}`;
    (values[key] ||= []).push(item[2].trim());
  }
  return values;
}

function walk(dir, out = []) {
  if (!existsSync(dir)) return out;
  for (const name of readdirSync(dir)) {
    const path = join(dir, name);
    if (statSync(path).isDirectory()) walk(path, out);
    else out.push(path);
  }
  return out;
}

const values = rigging();
const implDirs = values['Directories/implementation'] || [];
const specDirs = values['Directories/specs'] || [];
const verifyDirs = values['Directories/verification'] || [];

const sourceFiles = implDirs.flatMap((d) => walk(join(ROOT, d))).filter((f) => extname(f) === '.js');
const stepFiles = verifyDirs.flatMap((d) => walk(join(ROOT, d))).filter((f) => extname(f) === '.js');
const featureFiles = specDirs.flatMap((d) => walk(join(ROOT, d))).filter((f) => extname(f) === '.feature');

// Step-definition patterns.
const patterns = [];
for (const file of stepFiles) {
  const text = readFileSync(file, 'utf8');
  const re = /\b(?:Given|When|Then)\s*\(\s*(['"`])((?:\\.|(?!\1).)*)\1/g;
  let m;
  while ((m = re.exec(text)) !== null) patterns.push({ pattern: m[2], file });
}
const patternSet = new Set(patterns.map((p) => p.pattern));

// Scenarios, their tags, and their step texts.
const scenarios = [];
for (const file of featureFiles) {
  const rel = file.slice(ROOT.length + 1);
  let tags = [];
  let current = null;
  for (const raw of readFileSync(file, 'utf8').split('\n')) {
    const line = raw.trim();
    if (line.startsWith('@')) { tags = line.split(/\s+/); continue; }
    const head = line.match(/^(Scenario|Scenario Outline|Example):\s*(.+)$/);
    if (head) { current = { ref: `${rel}:${head[2].trim()}`, tags, steps: [] }; scenarios.push(current); tags = []; continue; }
    const step = line.match(/^(Given|When|Then|And|But)\s+(.+)$/);
    if (step && current) current.steps.push(step[2].trim());
  }
}
const captainRefs = new Set(scenarios.filter((s) => s.tags.includes('@captain')).map((s) => s.ref));

function patternMatches(pattern, stepText) {
  const source = pattern
    .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    .replace(/\\\{string\\\}/g, '"[^"]*"')
    .replace(/\\\{int\\\}/g, '-?\\d+')
    .replace(/\\\{float\\\}/g, '-?\\d+(?:\\.\\d+)?')
    .replace(/\\\{word\\\}/g, '\\S+');
  try { return new RegExp(`^${source}$`).test(stepText); } catch { return false; }
}

// Plank annotations.
const planks = [];
const faults = [];
for (const file of sourceFiles) {
  const rel = file.slice(ROOT.length + 1);
  const text = readFileSync(file, 'utf8');
  const lines = text.split('\n');
  const docblockPlanks = new Set();
  const docRe = /\/\*\*([\s\S]*?)\*\/\s*\n\s*(\S[^\n]*)/g;
  let m;
  while ((m = docRe.exec(text)) !== null) {
    const body = m[1];
    const declaration = m[2];
    const tagRe = /@(planks|planks-provisional)\(\s*"((?:\\.|[^"])*)"\s*\)/g;
    let t;
    while ((t = tagRe.exec(body)) !== null) {
      docblockPlanks.add(`${t[1]}:${t[2]}`);
      planks.push({ kind: t[1], value: t[2], file: rel, declaration });
    }
  }
  lines.forEach((line, index) => {
    const tagRe = /@(planks|planks-provisional)\(\s*"((?:\\.|[^"])*)"\s*\)/g;
    let t;
    while ((t = tagRe.exec(line)) !== null) {
      if (!docblockPlanks.has(`${t[1]}:${t[2]}`)) {
        faults.push(`${rel}:${index + 1}: plank outside a docblock on a declaration: @${t[1]}("${t[2]}")`);
      }
    }
  });
  const bare = text.match(/@planks(?!-provisional)(?!\s*\()/g);
  if (bare) faults.push(`${rel}: malformed plank token without a quoted pattern`);
  const declares = /^\s*(export\s+)?(async\s+)?(function|class|const|let|var)\s/m.test(text);
  if (declares && planks.filter((p) => p.file === rel).length === 0) {
    faults.push(`${rel}: production seam carries no @planks or @planks-provisional annotation`);
  }
}

for (const plank of planks) {
  if (plank.kind === 'planks' && !patternSet.has(plank.value)) {
    faults.push(`${plank.file}: @planks("${plank.value}") matches no current step-definition pattern`);
  }
  if (plank.kind === 'planks-provisional' && !captainRefs.has(plank.value)) {
    faults.push(`${plank.file}: @planks-provisional("${plank.value}") names no @captain scenario`);
  }
}

// The join: pattern to declaration to scenarios.
console.log('plank join');
for (const { pattern } of patterns) {
  const bound = scenarios
    .filter((s) => !s.tags.includes('@captain') && !s.tags.includes('@shipwright'))
    .filter((s) => s.steps.some((step) => patternMatches(pattern, step)))
    .map((s) => s.ref);
  const seams = planks.filter((p) => p.kind === 'planks' && p.value === pattern).map((p) => p.file);
  console.log(`  pattern "${pattern}" | seams: ${seams.join(', ') || 'none'} | scenarios: ${bound.length}`);
  if (bound.length === 0) faults.push(`orphaned step definition: "${pattern}" binds no live scenario`);
}
for (const plank of planks.filter((p) => p.kind === 'planks-provisional')) {
  console.log(`  provisional "${plank.value}" | seam: ${plank.file}`);
}
console.log(`patterns: ${patterns.length}  planks: ${planks.length}  scenarios: ${scenarios.length}`);

if (faults.length > 0) {
  console.error('plank join faults:');
  for (const fault of faults) console.error(`  ${fault}`);
  process.exit(1);
}
console.log('plank join clean');

