  "rules": [
    {
      "id": "no-guessed-delay",
      "scope": "verification",
      "forbidPattern": "setTimeout\\(\\s*(?:resolve|\\(\\)\\s*=>)[^,]*,\\s*\\d+",
      "allowMarker": "@exceptional-double",
      "message": "A guessed literal delay stands where a signal is observable. End the wait on an observed signal."
    },
    {
      "id": "no-forbidden-double",
      "scope": "verification",
      "forbidPattern": "\\b(sinon\\.(stub|mock|fake)|jest\\.(mock|fn)|createStub|createMock|FakeStorage)\\b",
      "allowMarker": "@exceptional-double",
      "message": "A test double stands unmarked. Real by default: mark and justify every double inline with @exceptional-double."
    },
    {
      "id": "no-hand-built-dom",
      "scope": "verification",
      "forbidPattern": "new\\s+Window\\(|createHTMLDocument\\(",
      "allowMarker": "@exceptional-double",
      "message": "Verification builds its own DOM instead of loading the real page and the real application through the world."
    },
    {
      "id": "plank-form",
      "scope": "implementation",
      "requireJoin": "plank-join",
      "message": "Every @planks and @planks-provisional token resolves to a docblock tag on a declaration, every @planks string is a current step-definition pattern, and every @planks-provisional reference names a scenario that still carries @captain."
    },
    {
      "id": "plank-coverage",
      "scope": "implementation",
      "requireJoin": "plank-join",
      "message": "Every production seam carries at least one plank, and every behaviour-bearing step-definition pattern is carried by at least one plank."
    }
  ]
}

